    class _HealpixRing:
        @staticmethod
        def nside2npix(nside):
            return 12*int(nside)*int(nside)
        @staticmethod
        def ang2pix(nside, theta, phi, nest=False):
            n=int(nside); th=np.asarray(theta,float); ph=np.asarray(phi,float)
            z=np.cos(th); za=np.abs(z); tt=np.mod(ph,2*np.pi)/(0.5*np.pi)
            npix=12*n*n; ncap=2*n*(n-1); nl4=4*n
            out=np.empty(np.broadcast(z,tt).shape,dtype=np.int64)
            z,tt=np.broadcast_arrays(z,tt); eq=za<=2/3
            temp1=n*(0.5+tt[eq]); temp2=n*z[eq]*0.75
            jp=np.floor(temp1-temp2).astype(np.int64); jm=np.floor(temp1+temp2).astype(np.int64)
            ir=n+1+jp-jm; kshift=1-(ir&1); t1=jp+jm-n+kshift+1+2*nl4
            ip=(t1//2)%nl4
            out[eq]=ncap+(ir-1)*nl4+ip
            pol=~eq
            if np.any(pol):
                zp=z[pol]; zap=np.abs(zp); ttp=tt[pol]; tp=ttp-np.floor(ttp)
                tmp=n*np.sqrt(3*(1-zap)); jpp=np.floor(tp*tmp).astype(np.int64); jmm=np.floor((1-tp)*tmp).astype(np.int64)
                irr=jpp+jmm+1; ipp=np.floor(ttp*irr).astype(np.int64)
                out[pol]=np.where(zp>0,2*irr*(irr-1)+ipp,npix-2*irr*(irr+1)+ipp)
            return int(out) if out.ndim==0 else out
        @staticmethod
        def pix2ang(nside, pix, nest=False):
            n=int(nside); p=np.asarray(pix,dtype=np.int64); scalar=p.ndim==0; p=np.atleast_1d(p)
            npix=12*n*n; ncap=2*n*(n-1); z=np.empty(p.size,float); phi=np.empty(p.size,float)
            north=p<ncap; eq=(p>=ncap)&(p<(npix-ncap)); south=~(north|eq)
            if np.any(north):
                pp=p[north]; ir=((1+np.floor(np.sqrt(1+2*pp)).astype(np.int64))//2)
                # integer sqrt correction for exact boundaries
                ir=np.array([(1+math.isqrt(1+2*int(x)))//2 for x in pp],dtype=np.int64)
                iphi=(pp+1)-2*ir*(ir-1); tmp=(ir.astype(float)**2)/(3*n*n)
                z[north]=1-tmp; phi[north]=(iphi-0.5)*(0.5*np.pi)/ir
            if np.any(eq):
                pp=p[eq]-ncap; ir=pp//(4*n)+n; iphi=pp%(4*n)+1; fodd=np.where(((ir+n)&1)==1,1.0,0.5)
                z[eq]=(2*n-ir)*(2/(3*n)); phi[eq]=(iphi-fodd)*np.pi/(2*n)
            if np.any(south):
                ip=npix-p[south]; ir=np.array([(1+math.isqrt(2*int(x)-1))//2 for x in ip],dtype=np.int64)
                iphi=4*ir+1-(ip-2*ir*(ir-1)); tmp=(ir.astype(float)**2)/(3*n*n)
                z[south]=tmp-1; phi[south]=(iphi-0.5)*(0.5*np.pi)/ir
            theta=np.arccos(np.clip(z,-1,1)); phi=np.mod(phi,2*np.pi)
            if scalar: return float(theta[0]),float(phi[0])
            return theta,phi
        @classmethod
        def pix2vec(cls,nside,pix,nest=False):
            th,ph=cls.pix2ang(nside,pix,nest=nest); st=np.sin(th); return np.array([st*np.cos(ph),st*np.sin(ph),np.cos(th)])
        @classmethod
        def query_disc(cls,nside,vec,radius,inclusive=False,nest=False):
            npix=cls.nside2npix(nside); th,ph=cls.pix2ang(nside,np.arange(npix)); st=np.sin(th)
            centers=np.column_stack([st*np.cos(ph),st*np.sin(ph),np.cos(th)]); v=np.asarray(vec,float); v=v/np.linalg.norm(v)
            return np.flatnonzero(centers@v >= np.cos(radius)-1e-15)
    hp=_HealpixRing()

