def resolve_default_data_dir(explicit: Optional[Path] = None) -> Path:
    """Resolve the DAQ directory without depending on Spyder's working directory.

    The user's current folder name is Data_Full_5_Center.  The historical
    Data_Full_5_Cent spelling is accepted only as a fallback for backward
    compatibility with earlier successful runs.  An explicitly supplied path
    is never silently replaced.
    """
    if explicit is not None:
        return Path(explicit).expanduser()
    if DEFAULT_DATA_DIR.is_dir():
        return DEFAULT_DATA_DIR
    if LEGACY_DATA_DIR.is_dir():
        return LEGACY_DATA_DIR
    return DEFAULT_DATA_DIR


