@dataclass
class RunSummary:
    run: str
    start_local: str
    daq_bin_count: int
    token_count: int
    candidate_count: int
    accepted_event_count: int
    duration_hours: float
    center_ch21: float
    center_ch31: float
    center_ch41: float
    center_ch51: float
