def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()



def preflight_data_directory_structure(data_dir: Path) -> None:
    """Fast structural check before network/catalog work or reconstruction."""
    directory=Path(data_dir).expanduser().resolve()
    if not directory.is_dir():
        raise FileNotFoundError(
            f'DAQ directory not found: {directory}. Expected the Desktop folder Data_Full_5_Center '
            '(the historical Data_Full_5_Cent name is accepted automatically when present).'
        )
    actual={p.name for p in directory.glob('*.txt')}
    expected=set(RUN_STARTS_LOCAL)
    if actual!=expected or len(actual)!=44:
        raise RuntimeError(
            'DAQ directory structure check failed before the long run; '
            f'missing={sorted(expected-actual)}, unexpected={sorted(actual-expected)}.'
        )
    if any(directory.glob('*.zip')):
        raise RuntimeError('Remove ZIP archives from the production DAQ directory before running V12.')
    print(f'[INPUT-PREFLIGHT] Found the exact expected set of 44 DAQ text files in {directory}.')


def discover_and_audit_data(data_dir: Path) -> tuple[list[Path], str]:
    directory = data_dir.expanduser().resolve()
    if not directory.is_dir():
        raise FileNotFoundError(f"DAQ directory not found: {directory}")
    files = sorted(directory.glob("*.txt"), key=lambda p: RUN_STARTS_LOCAL.get(p.name, datetime.max))
    expected = set(RUN_STARTS_LOCAL)
    actual = {p.name for p in files}
    if actual != expected or len(files) != 44:
        raise RuntimeError(
            "The DAQ directory must contain exactly the 44 mapped text files; "
            f"missing={sorted(expected-actual)}, unexpected={sorted(actual-expected)}."
        )
    if any(directory.glob("*.zip")):
        raise RuntimeError("Remove ZIP archives from the production DAQ directory.")
    rows: list[tuple[str, int, str]] = []
    for path in files:
        rows.append((path.name, path.stat().st_size, _sha256_file(path)))
    digest = hashlib.sha256()
    for name, size, file_hash in rows:
        digest.update(name.encode("utf-8") + b"\0")
        digest.update(str(size).encode("ascii") + b"\0")
        digest.update(file_hash.encode("ascii") + b"\n")
    total_bytes = sum(size for _, size, _ in rows)
    dataset_hash = digest.hexdigest()
    if total_bytes != EXPECTED_DATA_BYTES or dataset_hash != EXPECTED_DATA_SHA256:
        raise RuntimeError(
            "The 44-file data set does not match the audited byte count and SHA-256."
        )
    print("[INPUT] Validated the complete set of 44 uncompressed DAQ runs.")
    return files, dataset_hash



def read_daq_tokens(path: Path) -> np.ndarray:
    tokens = np.fromstring(path.read_text(encoding="ascii", errors="strict"), dtype=np.int32, sep=" ")
    if tokens.size == 0:
        raise RuntimeError(f"{path.name}: no integer DAQ tokens were read.")
    return tokens



def parse_fixed_width_records(
    path: Path, channel_min: int, channel_max: int
) -> tuple[np.ndarray, np.ndarray, tuple[np.ndarray, ...], dict[str, int]]:
    """Decode each 0.05-s record as multiplicity m followed by 4m ADC values.

    A zero multiplicity has no ADC payload but still advances the run clock by
    one bin.  Values inside a 4m payload are always treated as ADC data, even
    when an ADC value itself is zero.
    """

    tokens = read_daq_tokens(path)
    rows: list[np.ndarray] = []
    counters: list[int] = []
    calibration: tuple[list[int], ...] = ([], [], [], [])
    index = daq_bin = candidates = rejected = 0
    while index < len(tokens):
        marker = int(tokens[index])
        if marker < 0 or marker > 16:
            raise RuntimeError(
                f"{path.name}: invalid multiplicity {marker} at token {index:,}; record alignment failed."
            )
        index += 1
        this_counter = daq_bin
        # Every record represents elapsed time, including an empty m=0 record.
        daq_bin += 1
        payload_size = 4 * marker
        if index + payload_size > len(tokens):
            raise RuntimeError(f"{path.name}: truncated final DAQ record.")
        payload = tokens[index : index + payload_size]
        index += payload_size
        candidates += marker
        if marker == 0:
            continue
        for channels in payload.reshape(marker, 4):
            for column, value in enumerate(channels):
                if channel_min <= int(value) <= channel_max:
                    calibration[column].append(int(value))
            # D2-D1 is the event gate.  Only a candidate with a valid first
            # timing channel is tested for valid D3-D1, D4-D1, and D5-D1
            # channels and admitted to the four-detector direction fit.
            first_channel_valid = channel_min <= channels[0] <= channel_max
            if not first_channel_valid:
                rejected += 1
                continue
            remaining_channels_valid = np.all(
                (channels[1:] >= channel_min) & (channels[1:] <= channel_max)
            )
            if remaining_channels_valid:
                rows.append(np.asarray(channels, dtype=np.int32))
                counters.append(this_counter)
            else:
                rejected += 1
    if daq_bin + 4 * candidates != len(tokens):
        raise RuntimeError(f"{path.name}: exact DAQ token accounting failed.")
    audit = {
        "token_count": int(len(tokens)),
        "daq_bin_count": int(daq_bin),
        "candidate_count": int(candidates),
        "channel_rejected_count": int(rejected),
        "truncated_candidate_count": 0,
        "orphan_token_count": 0,
    }
    return (
        np.asarray(rows, dtype=float),
        np.asarray(counters, dtype=np.int64),
        tuple(np.asarray(values, dtype=float) for values in calibration),
        audit,
    )



def _gaussian(x: np.ndarray, amplitude: float, mean: float, sigma: float) -> np.ndarray:
    return amplitude * np.exp(-0.5 * ((x - mean) / sigma) ** 2)



def calibration_centers(
    samples: Sequence[np.ndarray], channel_min: int, channel_max: int
) -> np.ndarray:
    edges = np.arange(channel_min - 0.5, channel_max + 1.5, 1.0)
    fitted: list[float] = []
    for sample in samples:
        counts, bin_edges = np.histogram(sample, bins=edges)
        x = 0.5 * (bin_edges[:-1] + bin_edges[1:])
        try:
            parameters, _ = curve_fit(
                _gaussian,
                x,
                counts,
                p0=(max(int(counts.max()), 1), float(np.median(sample)), 40.0),
                bounds=([0.0, channel_min, 1.0], [np.inf, channel_max, 150.0]),
                maxfev=50_000,
            )
            fitted.append(float(parameters[1]))
        except (RuntimeError, ValueError):
            fitted.append(float(np.median(sample)))
    return np.asarray(fitted)



def reconstruct_angles(delays_seconds: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    geometry = DETECTOR_COORDS_M[1:] - DETECTOR_COORDS_M[0]
    solution = (C_AIR_M_PER_S * (np.linalg.pinv(geometry) @ delays_seconds.T)).T
    horizontal = np.linalg.norm(solution, axis=1)
    physical = horizontal < 1.0
    theta = np.full(len(solution), np.nan)
    phi = np.full(len(solution), np.nan)
    theta[physical] = np.degrees(np.arcsin(horizontal[physical]))
    phi[physical] = np.degrees(
        np.arctan2(-solution[physical, 1], solution[physical, 0])
    ) % 360.0
    return theta, phi



def local_datetimes(start_local: datetime, counters: np.ndarray) -> pd.DatetimeIndex:
    start = pd.Timestamp(start_local).tz_localize(TEHRAN_ZONE, ambiguous="raise", nonexistent="raise")
    utc_start = start.tz_convert("UTC")
    elapsed = pd.to_timedelta(np.asarray(counters, dtype=np.int64) * DT_SECONDS, unit="s")
    return pd.DatetimeIndex(utc_start + elapsed).tz_convert(TEHRAN_ZONE)



def utc_nanoseconds(times: pd.DatetimeIndex) -> np.ndarray:
    index = pd.DatetimeIndex(times)
    if index.tz is None:
        raise ValueError("Celestial timestamps must be timezone-aware.")
    return index.tz_convert("UTC").to_numpy(dtype="datetime64[ns]").astype(np.int64)



def days_since_j2000(times_utc: pd.DatetimeIndex) -> np.ndarray:
    return (
        utc_nanoseconds(times_utc).astype(np.float64) - 946_728_000_000_000_000.0
    ) / 86_400_000_000_000.0



def gmst_degrees(times_utc: pd.DatetimeIndex) -> np.ndarray:
    days = days_since_j2000(times_utc)
    centuries = days / 36525.0
    return (
        280.46061837
        + 360.98564736629 * days
        + 0.000387933 * centuries**2
        - centuries**3 / 38_710_000.0
    ) % 360.0



def precession_angles(times_utc: pd.DatetimeIndex) -> tuple[np.ndarray, ...]:
    centuries = days_since_j2000(times_utc) / 36525.0
    scale = math.pi / (180.0 * 3600.0)
    zeta = (2306.2181 * centuries + 0.30188 * centuries**2 + 0.017998 * centuries**3) * scale
    z = (2306.2181 * centuries + 1.09468 * centuries**2 + 0.018203 * centuries**3) * scale
    theta = (2004.3109 * centuries - 0.42665 * centuries**2 - 0.041833 * centuries**3) * scale
    return zeta, z, theta



def mean_of_date_to_icrs_with_angles(
    ra_deg: np.ndarray,
    dec_deg: np.ndarray,
    zeta: np.ndarray,
    z_angle: np.ndarray,
    theta_angle: np.ndarray,
) -> tuple[np.ndarray, np.ndarray]:
    ra = np.radians(np.asarray(ra_deg, dtype=float))
    dec = np.radians(np.asarray(dec_deg, dtype=float))
    x, y, z = np.cos(dec) * np.cos(ra), np.cos(dec) * np.sin(ra), np.sin(dec)
    x2 = np.cos(z_angle) * x + np.sin(z_angle) * y
    y2 = -np.sin(z_angle) * x + np.cos(z_angle) * y
    x1 = np.cos(theta_angle) * x2 + np.sin(theta_angle) * z
    z1 = -np.sin(theta_angle) * x2 + np.cos(theta_angle) * z
    x0 = np.cos(zeta) * x1 + np.sin(zeta) * y2
    y0 = -np.sin(zeta) * x1 + np.cos(zeta) * y2
    return np.degrees(np.arctan2(y0, x0)) % 360.0, np.degrees(np.arcsin(np.clip(z1, -1.0, 1.0)))



def local_declination_hour_angle(
    theta_deg: np.ndarray, phi_deg: np.ndarray
) -> tuple[np.ndarray, np.ndarray]:
    latitude = math.radians(SITE_LATITUDE_DEG)
    theta, phi = np.radians(theta_deg), np.radians(phi_deg)
    declination = np.arcsin(
        math.sin(latitude) * np.cos(theta)
        + math.cos(latitude) * np.sin(theta) * np.cos(phi)
    )
    hour_angle = np.arctan2(
        -np.sin(phi) * np.sin(theta),
        math.cos(latitude) * np.cos(theta)
        - math.sin(latitude) * np.sin(theta) * np.cos(phi),
    )
    return np.degrees(declination), np.degrees(hour_angle)



def local_to_equatorial(
    theta_deg: np.ndarray, phi_deg: np.ndarray, times_utc: pd.DatetimeIndex
) -> tuple[np.ndarray, np.ndarray]:
    dec_mean, hour_angle = local_declination_hour_angle(theta_deg, phi_deg)
    lst = (gmst_degrees(times_utc) + SITE_LONGITUDE_DEG) % 360.0
    return mean_of_date_to_icrs_with_angles(
        (lst - hour_angle) % 360.0, dec_mean, *precession_angles(times_utc)
    )



def equatorial_to_galactic(
    ra_deg: np.ndarray, dec_deg: np.ndarray
) -> tuple[np.ndarray, np.ndarray]:
    ra, dec = np.radians(ra_deg), np.radians(dec_deg)
    vectors = np.column_stack((np.cos(dec) * np.cos(ra), np.cos(dec) * np.sin(ra), np.sin(dec)))
    galactic = vectors @ ICRS_TO_GALACTIC.T
    return (
        np.degrees(np.arctan2(galactic[:, 1], galactic[:, 0])) % 360.0,
        np.degrees(np.arcsin(np.clip(galactic[:, 2], -1.0, 1.0))),
    )



def galactic_to_equatorial(
    longitude_deg: np.ndarray, latitude_deg: np.ndarray
) -> tuple[np.ndarray, np.ndarray]:
    longitude = np.radians(np.asarray(longitude_deg, dtype=float))
    latitude = np.radians(np.asarray(latitude_deg, dtype=float))
    galactic = np.column_stack(
        (
            np.cos(latitude) * np.cos(longitude),
            np.cos(latitude) * np.sin(longitude),
            np.sin(latitude),
        )
    )
    icrs = galactic @ ICRS_TO_GALACTIC
    return (
        np.degrees(np.arctan2(icrs[:, 1], icrs[:, 0])) % 360.0,
        np.degrees(np.arcsin(np.clip(icrs[:, 2], -1.0, 1.0))),
    )



def process_run(path: Path, config: Config) -> tuple[pd.DataFrame, RunSummary]:
    channels, counters, samples, audit = parse_fixed_width_records(
        path, config.channel_min, config.channel_max
    )
    sample_counts = np.asarray([len(sample) for sample in samples])
    if np.any(sample_counts < config.min_calibration_events):
        raise RuntimeError(f"{path.name}: insufficient timing-calibration events.")
    centers = calibration_centers(samples, config.channel_min, config.channel_max)
    corrected = (channels - centers) * SECONDS_PER_CHANNEL
    theta, phi_magnetic = reconstruct_angles(corrected)
    selected = np.isfinite(theta) & np.isfinite(phi_magnetic) & (theta < config.theta_max_deg)
    times_local = local_datetimes(RUN_STARTS_LOCAL[path.name], counters[selected])
    times_utc = times_local.tz_convert("UTC")
    phi_true = (phi_magnetic[selected] + config.magnetic_declination_deg) % 360.0
    ra, dec = local_to_equatorial(theta[selected], phi_true, times_utc)
    gal_l, gal_b = equatorial_to_galactic(ra, dec)
    events = pd.DataFrame(
        {
            "run": path.name,
            "daq_counter": counters[selected],
            # Keep timestamps as timezone-aware datetimes in memory.  CSV export
            # may serialize them to text, so load_or_reconstruct() normalizes the
            # column back to datetime64[ns, UTC] before any analysis step.
            "utc_time": times_utc,
            "ch21": channels[selected, 0].astype(np.int16),
            "ch31": channels[selected, 1].astype(np.int16),
            "ch41": channels[selected, 2].astype(np.int16),
            "ch51": channels[selected, 3].astype(np.int16),
            "theta_deg": theta[selected],
            "phi_deg": phi_true,
            "ra_deg": ra,
            "dec_deg": dec,
            "gal_l_deg": gal_l,
            "gal_b_deg": gal_b,
        }
    )
    summary = RunSummary(
        run=path.name,
        start_local=RUN_STARTS_LOCAL[path.name].isoformat(),
        daq_bin_count=audit["daq_bin_count"],
        token_count=audit["token_count"],
        candidate_count=audit["candidate_count"],
        accepted_event_count=int(selected.sum()),
        duration_hours=audit["daq_bin_count"] * DT_SECONDS / 3600.0,
        center_ch21=float(centers[0]),
        center_ch31=float(centers[1]),
        center_ch41=float(centers[2]),
        center_ch51=float(centers[3]),
        calibration_count_ch21=int(sample_counts[0]),
        calibration_count_ch31=int(sample_counts[1]),
        calibration_count_ch41=int(sample_counts[2]),
        calibration_count_ch51=int(sample_counts[3]),
        truncated_candidate_count=audit["truncated_candidate_count"],
        orphan_token_count=audit["orphan_token_count"],
    )
    return events, summary



def event_fingerprint(events: pd.DataFrame) -> str:
    digest = hashlib.sha256()
    columns = ["daq_counter", "ch21", "ch31", "ch41", "ch51"]
    for name in RUN_STARTS_LOCAL:
        subset = events.loc[events["run"].astype(str).eq(name)]
        digest.update(name.encode("ascii") + b"\0")
        digest.update(np.ascontiguousarray(subset[columns].to_numpy(dtype="<i8")).tobytes())
    return digest.hexdigest()



def static_checks() -> None:
    geometry = DETECTOR_COORDS_M[1:] - DETECTOR_COORDS_M[0]
    if np.linalg.matrix_rank(geometry) != 2:
        raise RuntimeError("Detector geometry is degenerate.")
    theta = np.array([5.0, 17.0, 31.0, 44.0])
    phi = np.array([0.0, 63.0, 127.0, 241.0])
    horizontal = np.sin(np.radians(theta))
    solution = np.column_stack((horizontal * np.cos(np.radians(phi)), -horizontal * np.sin(np.radians(phi))))
    delays = (geometry @ solution.T).T / C_AIR_M_PER_S
    fitted_theta, fitted_phi = reconstruct_angles(delays)
    if np.max(np.abs(fitted_theta - theta)) > 1.0e-10 or np.max(
        np.abs((fitted_phi - phi + 180.0) % 360.0 - 180.0)
    ) > 1.0e-10:
        raise RuntimeError("Detector-plane direction round-trip failed.")
    j2000 = pd.DatetimeIndex([pd.Timestamp("2000-01-01T12:00:00Z")])
    if abs(float(gmst_degrees(j2000)[0]) - 280.46061837) > 1.0e-8:
        raise RuntimeError("Sidereal-time anchor failed.")
    gal_l, gal_b = equatorial_to_galactic(
        np.array([266.4051, 192.85948]),
        np.array([-28.936175, 27.12825]),
    )
    galactic_center_error = abs(float(((gal_l[0] + 180.0) % 360.0) - 180.0))
    if (
        galactic_center_error > 1.0e-3
        or abs(float(gal_b[0])) > 1.0e-3
        or abs(float(gal_b[1]) - 90.0) > 1.0e-3
    ):
        raise RuntimeError("ICRS-to-Galactic reference direction failed.")
    print("[CHECK] Geometry, timing, sidereal-time, and celestial-coordinate checks passed.")



def load_or_reconstruct(config: Config) -> tuple[pd.DataFrame, pd.DataFrame]:
    if (config.event_cache is None) != (config.run_summary_cache is None):
        raise ValueError("--event-cache and --run-summary-cache must be supplied together.")
    if config.event_cache is not None:
        events = pd.read_csv(config.event_cache)
        summaries = pd.read_csv(config.run_summary_cache)
        print(f"[INPUT] Loaded reconstructed cache: {len(events):,} events in {events['run'].nunique()} runs.")
    else:
        files, _ = discover_and_audit_data(config.data_dir)
        event_frames: list[pd.DataFrame] = []
        summary_rows: list[dict[str, object]] = []
        for number, path in enumerate(files, 1):
            events_run, summary = process_run(path, config)
            event_frames.append(events_run)
            summary_rows.append(asdict(summary))
            if number % 10 == 0 or number == 44:
                print(f"[RECON] Completed {number}/44 runs.")
        events = pd.concat(event_frames, ignore_index=True)
        summaries = pd.DataFrame(summary_rows)

    # Enforce one canonical timezone-aware dtype for all downstream time-window tests.
    # regardless of whether events were reconstructed in memory or loaded from
    # the CSV cache.  This prevents string-vs-Timestamp comparisons in the
    # targeted weekly audit (notably with pandas/pyarrow-backed string arrays).
    events["utc_time"] = pd.to_datetime(
        events["utc_time"], utc=True, format="mixed", errors="raise"
    )

    fingerprint = event_fingerprint(events)
    livetime = float(summaries["duration_hours"].sum())
    if len(events) != EXPECTED_EVENT_COUNT or fingerprint != EXPECTED_EVENT_SHA256:
        raise RuntimeError("The accepted-event count or identity fingerprint differs from the audited reconstruction.")
    if abs(livetime - EXPECTED_LIVETIME_HOURS) > 5.0e-7:
        raise RuntimeError("The DAQ live time differs from the audited reconstruction.")
    if events["run"].nunique() != 44:
        raise RuntimeError("The reconstructed sample does not contain all 44 runs.")
    config.output_dir.mkdir(parents=True, exist_ok=True)
    if config.event_cache is None and config.save_event_cache:
        events.to_csv(config.output_dir / "reconstructed_events.csv.gz", index=False, compression="gzip")
        summaries.to_csv(config.output_dir / "run_summary.csv", index=False)
    print(f"[RECON] Accepted {len(events):,} events in {livetime:.6f} h.")
    return events, summaries



def healpix_pixels(longitude_deg: np.ndarray, latitude_deg: np.ndarray, nside: int) -> np.ndarray:
    return hp.ang2pix(
        nside,
        np.radians(90.0 - np.asarray(latitude_deg, dtype=float)),
        np.radians(np.asarray(longitude_deg, dtype=float) % 360.0),
        nest=False,
    )



def pixel_longitude_latitude(nside: int, pixels: np.ndarray | int) -> tuple[np.ndarray, np.ndarray]:
    theta, phi = hp.pix2ang(nside, pixels, nest=False)
    return np.degrees(phi) % 360.0, 90.0 - np.degrees(theta)



def aperture_matrix(nside: int, radius_deg: float) -> csr_matrix:
    """Return a sparse top-hat operator centered on every HEALPix pixel."""

    npix = hp.nside2npix(nside)
    vectors = np.column_stack(hp.pix2vec(nside, np.arange(npix), nest=False))
    rows: list[np.ndarray] = []
    columns: list[np.ndarray] = []
    for pixel, vector in enumerate(vectors):
        members = hp.query_disc(
            nside, vector, np.radians(radius_deg), inclusive=False, nest=False
        )
        rows.append(np.full(len(members), pixel, dtype=np.int32))
        columns.append(np.asarray(members, dtype=np.int32))
    row = np.concatenate(rows)
    column = np.concatenate(columns)
    return csr_matrix(
        (np.ones(len(row), dtype=np.int8), (row, column)),
        shape=(npix, npix),
    )



def equal_livetime_interval_definition(
    events: pd.DataFrame,
    summaries: pd.DataFrame,
    interval_count: int,
) -> tuple[np.ndarray, list[pd.Timestamp], np.ndarray]:
    """Divide the archive into equal intervals of accumulated DAQ live time.

    Calendar gaps between runs carry no exposure.  A boundary can therefore
    fall inside a run; its UTC label is obtained by advancing through the
    concatenated run livetimes and then mapping the resulting offset back to
    the relevant run clock.
    """

    if interval_count < 2:
        raise ValueError("At least two equal-live-exposure intervals are required.")
    order = {name: index for index, name in enumerate(RUN_STARTS_LOCAL)}
    timeline = summaries.copy()
    timeline["_order"] = timeline["run"].astype(str).map(order)
    if timeline["_order"].isna().any():
        raise RuntimeError("A run summary is not present in the audited run timeline.")
    timeline = timeline.sort_values("_order").reset_index(drop=True)
    durations = timeline["daq_bin_count"].to_numpy(float) * DT_SECONDS
    cumulative_edges = np.concatenate(([0.0], np.cumsum(durations)))
    total_live_seconds = float(cumulative_edges[-1])
    exposure_edges = np.linspace(0.0, total_live_seconds, interval_count + 1)
    live_hours = np.diff(exposure_edges) / 3600.0

    starts = [
        pd.Timestamp(RUN_STARTS_LOCAL[str(run)])
        .tz_localize(TEHRAN_ZONE, ambiguous="raise", nonexistent="raise")
        .tz_convert("UTC")
        for run in timeline["run"].astype(str)
    ]

    def exposure_to_utc(exposure_seconds: float) -> pd.Timestamp:
        if exposure_seconds <= 0.0:
            return starts[0]
        if exposure_seconds >= total_live_seconds:
            return starts[-1] + pd.Timedelta(durations[-1], unit="s")
        run_index = int(
            np.searchsorted(cumulative_edges[1:], exposure_seconds, side="right")
        )
        offset = exposure_seconds - cumulative_edges[run_index]
        return starts[run_index] + pd.Timedelta(offset, unit="s")

    boundaries = [exposure_to_utc(edge) for edge in exposure_edges]
    run_offsets = {
        str(run): float(cumulative_edges[index])
        for index, run in enumerate(timeline["run"].astype(str))
    }
    event_live_seconds = (
        events["run"].astype(str).map(run_offsets).to_numpy(float)
        + events["daq_counter"].to_numpy(float) * DT_SECONDS
    )
    if not np.all(np.isfinite(event_live_seconds)):
        raise RuntimeError("An event could not be placed on the accumulated-live-time axis.")
    interval = np.searchsorted(
        exposure_edges[1:-1], event_live_seconds, side="right"
    ).astype(np.int16)
    interval = np.clip(interval, 0, interval_count - 1)
    if len(np.unique(interval)) != interval_count:
        raise RuntimeError("At least one equal-live-exposure interval contains no events.")
    if float(np.ptp(live_hours)) > 1.0e-9:
        raise RuntimeError("The interval livetimes are not equal to numerical precision.")
    return interval, boundaries, live_hours



def observed_maps(
    events: pd.DataFrame,
    interval_id: np.ndarray,
    nside: int,
    aperture_operator: csr_matrix,
) -> tuple[np.ndarray, np.ndarray]:
    interval_count = int(interval_id.max()) + 1
    pixels = healpix_pixels(events["gal_l_deg"], events["gal_b_deg"], nside)
    raw = np.zeros((interval_count + 1, hp.nside2npix(nside)), dtype=np.int64)
    raw[0] = np.bincount(pixels, minlength=raw.shape[1])
    for interval in range(interval_count):
        raw[interval + 1] = np.bincount(
            pixels[interval_id == interval], minlength=raw.shape[1]
        )
    if int(raw[0].sum()) != len(events) or int(raw[1:].sum()) != len(events):
        raise RuntimeError("The sky maps did not retain every accepted event.")
    aperture = np.asarray([aperture_operator @ row for row in raw], dtype=float)
    return raw, aperture



@dataclass
class RandomizationState:
    declination_mean_deg: np.ndarray
    hour_angle_deg: np.ndarray
    observed_lst_deg: np.ndarray
    precession: tuple[np.ndarray, np.ndarray, np.ndarray]
    interval_id: np.ndarray
    blocks: list[np.ndarray]



def randomization_state(events: pd.DataFrame, config: Config, interval_id: np.ndarray) -> RandomizationState:
    times = pd.DatetimeIndex(pd.to_datetime(events["utc_time"], utc=True, format="mixed"))
    declination, hour_angle = local_declination_hour_angle(
        events["theta_deg"].to_numpy(float), events["phi_deg"].to_numpy(float)
    )
    block_number = np.floor(
        events["daq_counter"].to_numpy(float) * DT_SECONDS / (config.time_block_hours * 3600.0)
    ).astype(np.int64)
    keys = pd.DataFrame({"run": events["run"].astype(str), "block": block_number})
    blocks = [np.asarray(index, dtype=np.int64) for index in keys.groupby(["run", "block"], sort=False).indices.values()]
    if sum(map(len, blocks)) != len(events):
        raise RuntimeError("The randomization blocks do not cover every event.")
    return RandomizationState(
        declination_mean_deg=declination,
        hour_angle_deg=hour_angle,
        observed_lst_deg=(gmst_degrees(times) + SITE_LONGITUDE_DEG) % 360.0,
        precession=precession_angles(times),
        interval_id=np.asarray(interval_id, dtype=np.int16),
        blocks=blocks,
    )



def randomized_aperture_maps(
    state: RandomizationState,
    rng: np.random.Generator,
    nside: int,
    aperture_operator: csr_matrix,
) -> np.ndarray:
    count = len(state.hour_angle_deg)
    randomized_lst = np.empty(count, dtype=float)
    randomized_precession = tuple(np.empty(count, dtype=float) for _ in range(3))
    randomized_interval = np.empty(count, dtype=np.int16)
    for indices in state.blocks:
        reassigned = indices[rng.permutation(len(indices))]
        randomized_lst[indices] = state.observed_lst_deg[reassigned]
        randomized_interval[indices] = state.interval_id[reassigned]
        for destination, source in zip(randomized_precession, state.precession):
            destination[indices] = source[reassigned]
    ra, dec = mean_of_date_to_icrs_with_angles(
        (randomized_lst - state.hour_angle_deg) % 360.0,
        state.declination_mean_deg,
        *randomized_precession,
    )
    longitude, latitude = equatorial_to_galactic(ra, dec)
    interval_count = int(state.interval_id.max()) + 1
    pixels = healpix_pixels(longitude, latitude, nside)
    raw = np.zeros((interval_count + 1, hp.nside2npix(nside)), dtype=np.int64)
    raw[0] = np.bincount(pixels, minlength=raw.shape[1])
    for interval in range(interval_count):
        raw[interval + 1] = np.bincount(
            pixels[randomized_interval == interval], minlength=raw.shape[1]
        )
    return np.asarray([aperture_operator @ row for row in raw], dtype=float)



def realization_rng(base_seed: int, stream: int, trial: int) -> np.random.Generator:
    """Return a deterministic independent generator for one Monte Carlo sky."""
    return np.random.default_rng(
        np.random.SeedSequence([int(base_seed), int(stream), int(trial)])
    )



def high_occupancy_search_mask(
    reference_mean: np.ndarray,
    base_mask: np.ndarray,
    quantile: float,
) -> tuple[np.ndarray, np.ndarray]:
    """Restrict each map row to directions with adequate expected exposure.

    The threshold is defined from the randomized expected 8-degree aperture
    occupancy, not from the observed count, so an upward fluctuation is not
    used both to admit a direction and to raise its excess statistic.
    """
    if not 0.0 < quantile < 1.0:
        raise ValueError("high_occupancy_quantile must lie strictly between 0 and 1.")
    search_mask = np.zeros_like(base_mask, dtype=bool)
    thresholds = np.full(reference_mean.shape[0], np.nan, dtype=float)
    for row in range(reference_mean.shape[0]):
        values = reference_mean[row, base_mask[row]]
        if values.size == 0:
            raise RuntimeError("No statistically valid directions remain for the exposure screen.")
        thresholds[row] = float(np.quantile(values, quantile))
        search_mask[row] = base_mask[row] & (reference_mean[row] >= thresholds[row])
    return search_mask, thresholds



def randomization_state_fingerprint(state: RandomizationState) -> str:
    """Fingerprint the deterministic randomization state for safe MC resume."""
    h = hashlib.sha256()
    arrays = [state.hour_angle_deg, state.declination_mean_deg, state.observed_lst_deg,
              state.interval_id, *state.precession]
    for arr in arrays:
        a = np.ascontiguousarray(arr)
        h.update(str(a.dtype).encode("ascii")); h.update(str(a.shape).encode("ascii"))
        h.update(a.view(np.uint8).tobytes())
    for inds in state.blocks:
        a = np.ascontiguousarray(inds, dtype=np.int64)
        h.update(a.view(np.uint8).tobytes())
    return h.hexdigest()


def array_bundle_fingerprint(*arrays: np.ndarray) -> str:
    h = hashlib.sha256()
    for arr in arrays:
        a = np.ascontiguousarray(arr)
        h.update(str(a.dtype).encode("ascii")); h.update(str(a.shape).encode("ascii"))
        h.update(a.view(np.uint8).tobytes())
    return h.hexdigest()


def runtime_code_identity() -> dict[str, object]:
    """Return the exact on-disk identity of the Python file being executed."""
    path=Path(__file__).expanduser().resolve()
    return {'path':str(path),'bytes':int(path.stat().st_size),'sha256':_sha256_file(path)}


def _atomic_save_npz(path: Path, **payload) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + '.tmp.npz')
    np.savez_compressed(tmp, **payload)
    tmp.replace(path)


def _scalar_from_npz(data, key):
    value = data[key]
    return value.item() if getattr(value, 'shape', ()) == () else value


def reference_ensemble(
    state: RandomizationState,
    config: Config,
    aperture_operator: csr_matrix,
) -> tuple[
    np.ndarray,
    np.ndarray,
    np.ndarray,
    np.ndarray,
    np.random.Generator,
]:
    shape=(int(state.interval_id.max()) + 2, hp.nside2npix(config.nside))
    interval_count = int(state.interval_id.max()) + 1
    cumulative_shape=(interval_count, hp.nside2npix(config.nside))
    means=np.zeros(shape,dtype=float); m2=np.zeros(shape,dtype=float)
    cumulative_means=np.zeros(cumulative_shape,dtype=float); cumulative_m2=np.zeros(cumulative_shape,dtype=float)
    checkpoint=Path(config.output_dir)/'mc_checkpoint_reference_V12.npz'
    state_fp=randomization_state_fingerprint(state)
    operator_fp=array_bundle_fingerprint(aperture_operator.indptr,aperture_operator.indices,aperture_operator.data)
    code_sha=str(runtime_code_identity()['sha256'])
    start_trial=0
    if checkpoint.exists():
        try:
            with np.load(checkpoint,allow_pickle=False) as d:
                compatible=(str(_scalar_from_npz(d,'state_fingerprint'))==state_fp and
                            str(_scalar_from_npz(d,'operator_fingerprint'))==operator_fp and
                            str(_scalar_from_npz(d,'code_sha256'))==code_sha and
                            str(_scalar_from_npz(d,'release_id'))==RELEASE_ID and
                            int(_scalar_from_npz(d,'target_realizations'))==int(config.reference_realizations) and
                            int(_scalar_from_npz(d,'random_seed'))==int(config.random_seed) and
                            int(_scalar_from_npz(d,'nside'))==int(config.nside) and
                            abs(float(_scalar_from_npz(d,'aperture_radius_deg'))-float(config.aperture_radius_deg))<1e-12)
                if compatible:
                    start_trial=int(_scalar_from_npz(d,'completed_realizations'))
                    means=d['means'].copy(); m2=d['m2'].copy()
                    cumulative_means=d['cumulative_means'].copy(); cumulative_m2=d['cumulative_m2'].copy()
                    if not (0 <= start_trial <= config.reference_realizations): raise ValueError('invalid completed count')
                    print(f'[REFERENCE-RESUME] valid checkpoint found: {start_trial}/{config.reference_realizations}')
                else:
                    print('[REFERENCE-RESUME] checkpoint metadata does not match this run; starting reference ensemble from 0.')
        except Exception as exc:
            print(f'[REFERENCE-RESUME] checkpoint could not be used ({type(exc).__name__}: {exc}); starting from 0.')
            start_trial=0; means.fill(0); m2.fill(0); cumulative_means.fill(0); cumulative_m2.fill(0)
    progress=max(1,config.reference_realizations//5)
    print(f'[REFERENCE] {config.reference_realizations} short-block time-reassigned skies in {len(state.blocks)} blocks')
    for trial in range(start_trial,config.reference_realizations):
        trial_rng=realization_rng(config.random_seed,1,trial)
        maps=randomized_aperture_maps(state,trial_rng,config.nside,aperture_operator)
        delta=maps-means; means += delta/float(trial+1); m2 += delta*(maps-means)
        cumulative=np.cumsum(maps[1:],axis=0)
        cdelta=cumulative-cumulative_means; cumulative_means += cdelta/float(trial+1); cumulative_m2 += cdelta*(cumulative-cumulative_means)
        done=trial+1
        if done % int(config.mc_checkpoint_interval)==0 or done==config.reference_realizations:
            _atomic_save_npz(checkpoint,
                state_fingerprint=np.asarray(state_fp),operator_fingerprint=np.asarray(operator_fp),code_sha256=np.asarray(code_sha),
                release_id=np.asarray(RELEASE_ID),aperture_radius_deg=np.asarray(config.aperture_radius_deg),
                target_realizations=np.asarray(config.reference_realizations),completed_realizations=np.asarray(done),
                random_seed=np.asarray(config.random_seed),nside=np.asarray(config.nside),
                means=means,m2=m2,cumulative_means=cumulative_means,cumulative_m2=cumulative_m2)
            print(f'[REFERENCE-CHECKPOINT] saved {done}/{config.reference_realizations}')
        elif done % progress==0:
            print(f'[REFERENCE] {done}/{config.reference_realizations}')
    if config.reference_realizations < 2: raise ValueError('reference_realizations must be at least 2')
    standard_deviations=np.sqrt(m2/float(config.reference_realizations-1))
    cumulative_standard_deviations=np.sqrt(cumulative_m2/float(config.reference_realizations-1))
    return means,standard_deviations,cumulative_means,cumulative_standard_deviations,None

def standardized_excess(
    counts: np.ndarray,
    mean: np.ndarray,
    standard_deviation: np.ndarray,
    minimum_mean: float,
) -> tuple[np.ndarray, np.ndarray]:
    mask = (
        np.isfinite(mean)
        & np.isfinite(standard_deviation)
        & (mean >= minimum_mean)
        & (standard_deviation > 0.0)
    )
    values = np.full_like(mean, np.nan, dtype=float)
    np.divide(counts - mean, standard_deviation, out=values, where=mask)
    return values, mask



def peak_of_map(values: np.ndarray, mask: np.ndarray) -> tuple[int, float]:
    eligible = np.where(mask, values, -np.inf)
    pixel = int(np.argmax(eligible))
    return pixel, float(eligible[pixel])



def map_scan_calibration(
    state: RandomizationState,
    observed_aperture: np.ndarray,
    reference_mean: np.ndarray,
    reference_std: np.ndarray,
    cumulative_reference_mean: np.ndarray,
    cumulative_reference_std: np.ndarray,
    rng: np.random.Generator,
    config: Config,
    aperture_operator: csr_matrix,
    gamma_catalog_pixels: np.ndarray | None = None,
) -> dict[str, object]:
    interval_count=int(state.interval_id.max())+1
    observed_z,base_mask=standardized_excess(observed_aperture,reference_mean,reference_std,config.minimum_reference_count)
    mask,exposure_thresholds=high_occupancy_search_mask(reference_mean,base_mask,config.high_occupancy_quantile)
    observed_peaks=[]
    for row in range(interval_count+1):
        pixel,value=peak_of_map(observed_z[row],mask[row]); observed_peaks.append({'pixel':pixel,'z':value})
    primary_pixel=int(observed_peaks[0]['pixel']); observed_full_max=float(observed_peaks[0]['z'])
    K=int(config.look_elsewhere_realizations)
    null_full_max=np.empty(K,float); null_local_primary=np.empty(K,float)
    null_interval_max=np.empty((K,interval_count),float); null_cumulative_primary=np.empty_like(null_interval_max)

    gamma_pixels=np.asarray([] if gamma_catalog_pixels is None else gamma_catalog_pixels,dtype=np.int64)
    gamma_valid_all=[]; gamma_valid_high=[]; observed_gamma_max_all=[]; observed_gamma_max_high=[]
    for row in range(interval_count+1):
        gp_all=gamma_pixels[base_mask[row,gamma_pixels]] if gamma_pixels.size else np.asarray([],dtype=np.int64)
        gp_high=gamma_pixels[mask[row,gamma_pixels]] if gamma_pixels.size else np.asarray([],dtype=np.int64)
        gamma_valid_all.append(gp_all); gamma_valid_high.append(gp_high)
        observed_gamma_max_all.append(float(np.nanmax(observed_z[row,gp_all])) if len(gp_all) else np.nan)
        observed_gamma_max_high.append(float(np.nanmax(observed_z[row,gp_high])) if len(gp_high) else np.nan)
    null_gamma_full_all=np.full(K,np.nan,float); null_gamma_interval_all=np.full((K,interval_count),np.nan,float)
    null_gamma_full_high=np.full(K,np.nan,float); null_gamma_interval_high=np.full((K,interval_count),np.nan,float)

    checkpoint=Path(config.output_dir)/'mc_checkpoint_calibration_V12.npz'
    state_fp=randomization_state_fingerprint(state)
    code_sha=str(runtime_code_identity()['sha256'])
    analysis_fp=array_bundle_fingerprint(reference_mean,reference_std,cumulative_reference_mean,cumulative_reference_std,
                                         mask.astype(np.uint8),base_mask.astype(np.uint8),gamma_pixels,
                                         np.asarray([primary_pixel],dtype=np.int64))
    start_trial=0
    if checkpoint.exists():
        try:
            with np.load(checkpoint,allow_pickle=False) as d:
                compatible=(str(_scalar_from_npz(d,'state_fingerprint'))==state_fp and
                            str(_scalar_from_npz(d,'analysis_fingerprint'))==analysis_fp and
                            str(_scalar_from_npz(d,'code_sha256'))==code_sha and
                            str(_scalar_from_npz(d,'release_id'))==RELEASE_ID and
                            int(_scalar_from_npz(d,'target_realizations'))==K and
                            int(_scalar_from_npz(d,'random_seed'))==int(config.random_seed) and
                            int(_scalar_from_npz(d,'nside'))==int(config.nside))
                if compatible:
                    start_trial=int(_scalar_from_npz(d,'completed_realizations'))
                    null_full_max[:start_trial]=d['null_full_max'][:start_trial]; null_local_primary[:start_trial]=d['null_local_primary'][:start_trial]
                    null_interval_max[:start_trial]=d['null_interval_max'][:start_trial]; null_cumulative_primary[:start_trial]=d['null_cumulative_primary'][:start_trial]
                    null_gamma_full_all[:start_trial]=d['null_gamma_full_all'][:start_trial]; null_gamma_interval_all[:start_trial]=d['null_gamma_interval_all'][:start_trial]
                    null_gamma_full_high[:start_trial]=d['null_gamma_full_high'][:start_trial]; null_gamma_interval_high[:start_trial]=d['null_gamma_interval_high'][:start_trial]
                    if not (0 <= start_trial <= K): raise ValueError('invalid completed count')
                    print(f'[LOOK-ELSEWHERE-RESUME] valid checkpoint found: {start_trial}/{K}')
                else:
                    print('[LOOK-ELSEWHERE-RESUME] checkpoint metadata does not match this run; starting calibration from 0.')
        except Exception as exc:
            print(f'[LOOK-ELSEWHERE-RESUME] checkpoint could not be used ({type(exc).__name__}: {exc}); starting from 0.')
            start_trial=0
    progress=max(1,K//10)
    print(f'[LOOK-ELSEWHERE] {K} independent randomized skies for blind-map and catalog-family calibration')
    for trial in range(start_trial,K):
        trial_rng=realization_rng(config.random_seed,2,trial)
        maps=randomized_aperture_maps(state,trial_rng,config.nside,aperture_operator)
        z,_=standardized_excess(maps,reference_mean,reference_std,config.minimum_reference_count)
        null_full_max[trial]=float(np.nanmax(np.where(mask[0],z[0],np.nan)))
        null_local_primary[trial]=float(z[0,primary_pixel])
        if len(gamma_valid_all[0]): null_gamma_full_all[trial]=float(np.nanmax(z[0,gamma_valid_all[0]]))
        if len(gamma_valid_high[0]): null_gamma_full_high[trial]=float(np.nanmax(z[0,gamma_valid_high[0]]))
        for interval in range(interval_count):
            row=interval+1
            null_interval_max[trial,interval]=float(np.nanmax(np.where(mask[row],z[row],np.nan)))
            if len(gamma_valid_all[row]): null_gamma_interval_all[trial,interval]=float(np.nanmax(z[row,gamma_valid_all[row]]))
            if len(gamma_valid_high[row]): null_gamma_interval_high[trial,interval]=float(np.nanmax(z[row,gamma_valid_high[row]]))
        cumulative_maps=np.cumsum(maps[1:],axis=0)
        cumulative_z,_=standardized_excess(cumulative_maps,cumulative_reference_mean,cumulative_reference_std,config.minimum_reference_count)
        null_cumulative_primary[trial]=cumulative_z[:,primary_pixel]
        done=trial+1
        if done % int(config.mc_checkpoint_interval)==0 or done==K:
            _atomic_save_npz(checkpoint,
                state_fingerprint=np.asarray(state_fp),analysis_fingerprint=np.asarray(analysis_fp),code_sha256=np.asarray(code_sha),
                release_id=np.asarray(RELEASE_ID),target_realizations=np.asarray(K),
                completed_realizations=np.asarray(done),random_seed=np.asarray(config.random_seed),nside=np.asarray(config.nside),
                null_full_max=null_full_max[:done],null_local_primary=null_local_primary[:done],null_interval_max=null_interval_max[:done],
                null_cumulative_primary=null_cumulative_primary[:done],null_gamma_full_all=null_gamma_full_all[:done],
                null_gamma_interval_all=null_gamma_interval_all[:done],null_gamma_full_high=null_gamma_full_high[:done],
                null_gamma_interval_high=null_gamma_interval_high[:done])
            print(f'[LOOK-ELSEWHERE-CHECKPOINT] saved {done}/{K}')
        elif done % progress==0:
            print(f'[LOOK-ELSEWHERE] {done}/{K}')

    local_p=(1+np.sum(null_local_primary>=observed_full_max))/(K+1.0)
    map_wide_p=(1+np.sum(null_full_max>=observed_full_max))/(K+1.0)
    interval_peak_z=np.asarray([float(peak['z']) for peak in observed_peaks[1:]],float)
    interval_map_wide_p=(1+np.sum(null_interval_max>=interval_peak_z[None,:],axis=0))/(K+1.0)
    observed_six_interval_max=float(np.max(interval_peak_z)); null_six_interval_max=np.max(null_interval_max,axis=1)
    six_interval_family_p=(1+np.sum(null_six_interval_max>=observed_six_interval_max))/(K+1.0)

    def family_ps(obs, nf, ni):
        full=float((1+np.sum(nf>=obs[0]))/(K+1.0)) if np.isfinite(obs[0]) else np.nan
        interval=[]
        for i in range(interval_count):
            interval.append(float((1+np.sum(ni[:,i]>=obs[i+1]))/(K+1.0)) if np.isfinite(obs[i+1]) else np.nan)
        obs_six=float(np.nanmax(obs[1:])) if np.any(np.isfinite(obs[1:])) else np.nan
        null_six=np.nanmax(ni,axis=1)
        six=float((1+np.sum(null_six>=obs_six))/(K+1.0)) if np.isfinite(obs_six) else np.nan
        return full,np.asarray(interval,float),six
    gamma_all_full_p,gamma_all_interval_p,gamma_all_six_p=family_ps(observed_gamma_max_all,null_gamma_full_all,null_gamma_interval_all)
    gamma_high_full_p,gamma_high_interval_p,gamma_high_six_p=family_ps(observed_gamma_max_high,null_gamma_full_high,null_gamma_interval_high)

    return {
        'observed_z':observed_z,'search_mask':mask,'base_valid_mask':base_mask,'high_occupancy_thresholds':exposure_thresholds,
        'observed_peaks':observed_peaks,'primary_pixel':primary_pixel,'primary_local_z':observed_full_max,
        'primary_local_p_empirical':float(local_p),'map_wide_p':float(map_wide_p),'null_full_max':null_full_max,
        'interval_map_wide_p':interval_map_wide_p,'six_interval_family_p':float(six_interval_family_p),
        'null_interval_max':null_interval_max,'null_cumulative_primary':null_cumulative_primary,'gamma_catalog_pixels':gamma_pixels,
        'gamma_catalog_all_observed_max':np.asarray(observed_gamma_max_all,float),'gamma_catalog_all_full_p':gamma_all_full_p,
        'gamma_catalog_all_interval_p':gamma_all_interval_p,'gamma_catalog_all_six_interval_family_p':gamma_all_six_p,
        'gamma_catalog_all_valid_pixel_count':np.asarray([len(x) for x in gamma_valid_all],dtype=int),
        'gamma_catalog_high_occ_observed_max':np.asarray(observed_gamma_max_high,float),'gamma_catalog_high_occ_full_p':gamma_high_full_p,
        'gamma_catalog_high_occ_interval_p':gamma_high_interval_p,'gamma_catalog_high_occ_six_interval_family_p':gamma_high_six_p,
        'gamma_catalog_high_occ_pixel_count':np.asarray([len(x) for x in gamma_valid_high],dtype=int),
        # Compatibility aliases: the unqualified catalog family means all statistically valid source pixels.
        'gamma_catalog_observed_max':np.asarray(observed_gamma_max_all,float),'gamma_catalog_full_p':gamma_all_full_p,
        'gamma_catalog_interval_p':gamma_all_interval_p,'gamma_catalog_six_interval_family_p':gamma_all_six_p,
    }

def angular_separation_deg(
    longitude_one: np.ndarray | float,
    latitude_one: np.ndarray | float,
    longitude_two: np.ndarray | float,
    latitude_two: np.ndarray | float,
) -> np.ndarray:
    l1, b1, l2, b2 = map(np.radians, np.broadcast_arrays(longitude_one, latitude_one, longitude_two, latitude_two))
    cosine = np.sin(b1) * np.sin(b2) + np.cos(b1) * np.cos(b2) * np.cos(l1 - l2)
    return np.degrees(np.arccos(np.clip(cosine, -1.0, 1.0)))



def catalog_table() -> pd.DataFrame:
    catalog = pd.read_csv(io.StringIO(LHAASO_CATALOG_CSV))
    longitude, latitude = equatorial_to_galactic(
        catalog["ra_deg"].to_numpy(float), catalog["dec_deg"].to_numpy(float)
    )
    catalog["gal_l_deg"] = longitude
    catalog["gal_b_deg"] = latitude
    return catalog



def fit_sqrt_exposure_gls(
    cumulative_z: np.ndarray,
    cumulative_live_hours: np.ndarray,
    null_cumulative_z: np.ndarray,
) -> tuple[np.ndarray, dict[str, object]]:
    """Fit the normalization of Z=a*sqrt(T/T_total) with empirical covariance.

    The cumulative measurements are nested and therefore strongly correlated.
    Their covariance is estimated from the independent calibration skies at the
    same fixed direction.  The one-parameter generalized least-squares fit is
    not constrained to pass through the final observed point.
    """

    values = np.asarray(cumulative_z, dtype=float)
    live = np.asarray(cumulative_live_hours, dtype=float)
    null_values = np.asarray(null_cumulative_z, dtype=float)
    if null_values.ndim != 2 or null_values.shape[1] != len(values):
        raise ValueError("The cumulative null ensemble has the wrong shape.")
    if not np.all(np.isfinite(values)) or not np.all(np.isfinite(null_values)):
        raise RuntimeError("The cumulative significance fit received non-finite values.")
    design = np.sqrt(live / float(live[-1]))
    covariance = np.cov(null_values, rowvar=False, ddof=1)
    ridge = max(1.0e-10, 1.0e-8 * float(np.trace(covariance)) / len(values))
    regularized = covariance + ridge * np.eye(len(values))
    inverse = np.linalg.pinv(regularized, hermitian=True)
    denominator = float(design @ inverse @ design)
    if denominator <= 0.0:
        raise RuntimeError("The cumulative covariance does not support the GLS fit.")
    amplitude = float((design @ inverse @ values) / denominator)
    fitted = amplitude * design
    residual = values - fitted
    chi_square = float(residual @ inverse @ residual)
    degrees_of_freedom = max(1, len(values) - 1)
    fit_summary: dict[str, object] = {
        "method": "one_parameter_GLS_with_randomization_covariance",
        "full_exposure_normalization_z": amplitude,
        "normalization_standard_error": math.sqrt(1.0 / denominator),
        "chi_square": chi_square,
        "degrees_of_freedom": degrees_of_freedom,
        "goodness_of_fit_p": float(chi2.sf(chi_square, degrees_of_freedom)),
        "endpoint_anchor_z": float(values[-1]),
        "covariance_matrix": covariance.tolist(),
    }
    return fitted, fit_summary



def temporal_results(
    primary_pixel: int,
    observed_aperture: np.ndarray,
    reference_mean: np.ndarray,
    reference_std: np.ndarray,
    cumulative_reference_mean: np.ndarray,
    cumulative_reference_std: np.ndarray,
    interval_live_hours: np.ndarray,
    boundaries: Sequence[pd.Timestamp],
    search: dict[str, object],
    nside: int,
) -> tuple[pd.DataFrame, dict[str, object]]:
    observed = observed_aperture[1:, primary_pixel]
    mean = reference_mean[1:, primary_pixel]
    std = reference_std[1:, primary_pixel]
    disjoint_z = np.divide(observed - mean, std, out=np.full_like(mean, np.nan), where=std > 0.0)
    cumulative_observed = np.cumsum(observed)
    cumulative_mean = cumulative_reference_mean[:, primary_pixel]
    cumulative_std = cumulative_reference_std[:, primary_pixel]
    cumulative_z = np.divide(
        cumulative_observed - cumulative_mean,
        cumulative_std,
        out=np.full_like(cumulative_mean, np.nan),
        where=cumulative_std > 0.0,
    )
    cumulative_live = np.cumsum(interval_live_hours)
    fitted_track, fit_summary = fit_sqrt_exposure_gls(
        cumulative_z,
        cumulative_live,
        np.asarray(search["null_cumulative_primary"], dtype=float),
    )
    fit_summary["mean_disjoint_z"] = float(np.mean(disjoint_z))
    fit_summary["mean_disjoint_implied_full_exposure_z"] = float(
        np.mean(disjoint_z) * math.sqrt(len(disjoint_z))
    )
    interval_map_p = np.asarray(search["interval_map_wide_p"], dtype=float)
    rows = []
    for index in range(len(interval_live_hours)):
        peak = search["observed_peaks"][index + 1]
        peak_pixel = int(peak["pixel"])
        peak_l, peak_b = pixel_longitude_latitude(nside, peak_pixel)
        rows.append(
            {
                "interval": index + 1,
                "start_utc": boundaries[index].isoformat(),
                "stop_utc": boundaries[index + 1].isoformat(),
                "livetime_hours": float(interval_live_hours[index]),
                "observed_aperture_count": int(observed[index]),
                "reference_mean": float(mean[index]),
                "reference_std": float(std[index]),
                "fixed_candidate_z": float(disjoint_z[index]),
                "cumulative_z": float(cumulative_z[index]),
                "sqrt_exposure_fit": float(fitted_track[index]),
                "interval_peak_pixel": peak_pixel,
                "interval_peak_l_deg": float(peak_l),
                "interval_peak_b_deg": float(peak_b),
                "interval_peak_z": float(peak["z"]),
                "interval_peak_map_wide_p": float(interval_map_p[index]),
            }
        )
    return pd.DataFrame(rows), fit_summary



def data_quality_audit(
    events: pd.DataFrame,
    summaries: pd.DataFrame,
    interval_id: np.ndarray,
    interval_live_hours: np.ndarray,
) -> tuple[pd.DataFrame, pd.DataFrame, dict[str, object]]:
    """Quantify runwise and equal-exposure stability of the accepted data."""

    event_table = events.copy()
    event_table["_interval"] = np.asarray(interval_id, dtype=np.int16)
    grouped = event_table.groupby("run", sort=False)
    event_counts = grouped.size()
    theta_median = grouped["theta_deg"].median()
    theta_q25 = grouped["theta_deg"].quantile(0.25)
    theta_q75 = grouped["theta_deg"].quantile(0.75)
    run_table = summaries.copy()
    run_table["accepted_count_recounted"] = (
        run_table["run"].astype(str).map(event_counts).fillna(0).astype(int)
    )
    if not np.array_equal(
        run_table["accepted_count_recounted"].to_numpy(int),
        run_table["accepted_event_count"].to_numpy(int),
    ):
        raise RuntimeError("The runwise accepted-event recount does not match reconstruction.")
    run_table["accepted_rate_per_hour"] = (
        run_table["accepted_event_count"].to_numpy(float)
        / run_table["duration_hours"].to_numpy(float)
    )
    run_table["theta_median_deg"] = run_table["run"].astype(str).map(theta_median)
    run_table["theta_q25_deg"] = run_table["run"].astype(str).map(theta_q25)
    run_table["theta_q75_deg"] = run_table["run"].astype(str).map(theta_q75)
    start_utc = pd.DatetimeIndex(
        [
            pd.Timestamp(RUN_STARTS_LOCAL[str(run)])
            .tz_localize(TEHRAN_ZONE, ambiguous="raise", nonexistent="raise")
            .tz_convert("UTC")
            for run in run_table["run"].astype(str)
        ]
    )
    run_table["start_utc"] = start_utc.astype(str)
    run_table["midpoint_utc"] = (
        start_utc
        + pd.to_timedelta(
            0.5 * run_table["duration_hours"].to_numpy(float), unit="h"
        )
    ).astype(str)
    rates = run_table["accepted_rate_per_hour"].to_numpy(float)
    rate_median = float(np.median(rates))
    rate_mad = float(np.median(np.abs(rates - rate_median)))
    if rate_mad > 0.0:
        robust_z = 0.6744897501960817 * (rates - rate_median) / rate_mad
    else:
        robust_z = np.zeros_like(rates)
    run_table["accepted_rate_robust_z"] = robust_z

    interval_rows: list[dict[str, object]] = []
    for interval in range(len(interval_live_hours)):
        selected = np.asarray(interval_id) == interval
        theta = events.loc[selected, "theta_deg"].to_numpy(float)
        count = int(np.count_nonzero(selected))
        interval_rows.append(
            {
                "interval": interval + 1,
                "livetime_hours": float(interval_live_hours[interval]),
                "accepted_event_count": count,
                "accepted_rate_per_hour": count / float(interval_live_hours[interval]),
                "theta_median_deg": float(np.median(theta)),
                "theta_q25_deg": float(np.quantile(theta, 0.25)),
                "theta_q75_deg": float(np.quantile(theta, 0.75)),
            }
        )
    interval_table = pd.DataFrame(interval_rows)
    interval_rates = interval_table["accepted_rate_per_hour"].to_numpy(float)
    channel_ranges = {
        channel: {
            "minimum": float(run_table[channel].min()),
            "maximum": float(run_table[channel].max()),
            "range": float(run_table[channel].max() - run_table[channel].min()),
        }
        for channel in ("center_ch21", "center_ch31", "center_ch41", "center_ch51")
    }
    largest_index = int(np.argmax(np.abs(robust_z)))
    summary: dict[str, object] = {
        "run_count": int(len(run_table)),
        "run_rate_min_per_hour": float(np.min(rates)),
        "run_rate_max_per_hour": float(np.max(rates)),
        "run_rate_median_per_hour": rate_median,
        "run_rate_coefficient_of_variation": float(np.std(rates, ddof=1) / np.mean(rates)),
        "run_rate_mad_per_hour": rate_mad,
        "run_rate_abs_robust_z_above_5_count": int(np.count_nonzero(np.abs(robust_z) > 5.0)),
        "largest_abs_run_rate_robust_z": float(np.abs(robust_z[largest_index])),
        "largest_abs_run_rate_robust_z_run": str(run_table.iloc[largest_index]["run"]),
        "interval_rate_min_per_hour": float(np.min(interval_rates)),
        "interval_rate_max_per_hour": float(np.max(interval_rates)),
        "interval_rate_coefficient_of_variation": float(
            np.std(interval_rates, ddof=1) / np.mean(interval_rates)
        ),
        "interval_theta_median_min_deg": float(interval_table["theta_median_deg"].min()),
        "interval_theta_median_max_deg": float(interval_table["theta_median_deg"].max()),
        "timing_center_ranges": channel_ranges,
    }
    return run_table, interval_table, summary



def spatially_distinct_peaks(
    values: np.ndarray,
    nside: int,
    minimum_separation_deg: float,
    number: int = 5,
    eligible: Optional[np.ndarray] = None,
) -> list[int]:
    """Select descending peaks while suppressing neighboring trial centers."""

    array = np.asarray(values, dtype=float)
    allowed = np.isfinite(array)
    if eligible is not None:
        allowed &= np.asarray(eligible, dtype=bool)
    order = np.argsort(np.where(allowed, array, -np.inf))[::-1]
    selected: list[int] = []
    selected_longitudes: list[float] = []
    selected_latitudes: list[float] = []
    for pixel in order:
        if not allowed[pixel]:
            continue
        longitude, latitude = pixel_longitude_latitude(nside, int(pixel))
        if selected and np.any(
            angular_separation_deg(
                float(longitude),
                float(latitude),
                np.asarray(selected_longitudes),
                np.asarray(selected_latitudes),
            )
            < minimum_separation_deg
        ):
            continue
        selected.append(int(pixel))
        selected_longitudes.append(float(longitude))
        selected_latitudes.append(float(latitude))
        if len(selected) == number:
            break
    return selected



def top_candidate_table(observed_z, search_mask, observed_aperture, reference_mean, reference_std, live_hours, config):
    rows=[]
    for r in range(observed_z.shape[0]):
        pixels=spatially_distinct_peaks(observed_z[r],config.nside,config.candidate_separation_deg,config.top_candidate_count,search_mask[r])
        hours=float(np.sum(live_hours) if r==0 else live_hours[r-1])
        period="full" if r==0 else f"interval_{r}"
        for rank,p in enumerate(pixels,1):
            l,b=pixel_longitude_latitude(config.nside,p)
            ra,dec=galactic_to_equatorial(np.array([float(l)]),np.array([float(b)]))
            rows.append({"period":period,"rank":rank,"pixel":p,"l_deg":float(l),"b_deg":float(b),"ra_deg":float(ra[0]),"dec_deg":float(dec[0]),"z":float(observed_z[r,p]),"n_p":int(observed_aperture[r,p]),"b_p":float(reference_mean[r,p]),"reference_std":float(reference_std[r,p]),"observed_rate_per_hour":float(observed_aperture[r,p]/hours),"expected_rate_per_hour":float(reference_mean[r,p]/hours)})
    return pd.DataFrame(rows)

def interval_for_time(value, boundaries):
    t=pd.Timestamp(value)
    if t.tzinfo is None: t=t.tz_localize('UTC')
    else: t=t.tz_convert('UTC')
    for i in range(len(boundaries)-1):
        if boundaries[i] <= t < boundaries[i+1]: return i+1
    return None

def interval_for_calendar_date(value, boundaries):
    day=pd.Timestamp(value).date(); days=[pd.Timestamp(x).date() for x in boundaries]
    for i in range(len(days)-1):
        if days[i] <= day < days[i+1]: return i+1
    return None

def lhaaso_audit(top, observed_z, observed_aperture, reference_mean, config):
    cat=catalog_table().rename(columns={"source_name":"source"})
    rows=[]
    for _,c in top.iterrows():
        for _,s in cat.iterrows():
            d=float(angular_separation_deg(c.l_deg,c.b_deg,s.gal_l_deg,s.gal_b_deg))
            if d>config.aperture_radius_deg: continue
            row=0 if c.period=='full' else int(str(c.period).split('_')[1])
            p=int(hp.ang2pix(config.nside,np.radians(90-s.gal_b_deg),np.radians(s.gal_l_deg%360),nest=False))
            rows.append({"period":c.period,"candidate_rank":int(c['rank']),"candidate_l_deg":c.l_deg,"candidate_b_deg":c.b_deg,"candidate_z":c.z,"source":f"1LHAASO {s.source}u","source_l_deg":s.gal_l_deg,"source_b_deg":s.gal_b_deg,"separation_deg":d,"map_cell_pixel":p,"map_cell_z":float(observed_z[row,p]),"map_cell_n":int(observed_aperture[row,p]),"map_cell_b":float(reference_mean[row,p]),"map_cell_note":"HEALPix-cell statistic for spatial context only; not an exact source-centered test","flux_norm_50tev":s.flux_norm_50tev,"ts100":s.ts100})
    return pd.DataFrame(rows).sort_values(["period","separation_deg"])

def fava_audit(top, boundaries, config):
    fava=pd.read_csv(io.StringIO(FAVA_ARCHIVE_CSV))
    fava['time']=pd.to_datetime(fava['week_start_utc'],utc=True)
    fava['interval']=[interval_for_calendar_date(x,boundaries) for x in fava['time']]
    rows=[]
    interval_top=top[top.period!='full'].copy(); interval_top['interval']=interval_top.period.str.split('_').str[-1].astype(int)
    for _,f in fava.dropna(subset=['interval']).iterrows():
        cand=interval_top[interval_top.interval==int(f.interval)]
        if cand.empty: continue
        d=angular_separation_deg(cand.l_deg.to_numpy(),cand.b_deg.to_numpy(),float(f.l_deg),float(f.b_deg))
        for idx in np.where(d<=config.aperture_radius_deg)[0]:
            c=cand.iloc[int(idx)]
            association="" if pd.isna(f.association) else str(f.association)
            rows.append({"interval":int(f.interval),"candidate_rank":int(c['rank']),"candidate_l_deg":c.l_deg,"candidate_b_deg":c.b_deg,"candidate_z":c.z,"week":int(f.week),"week_start_utc":f.time.isoformat(),"fava_id":f.flare_id,"fava_sigma":float(f.sigma),"fava_association":association,"source_name":FAVA_ASSOCIATIONS.get(association,association),"fava_ra_deg":float(f.ra_deg),"fava_dec_deg":float(f.dec_deg),"fava_l_deg":float(f.l_deg),"fava_b_deg":float(f.b_deg),"separation_deg":float(d[idx])})
    if not rows:
        return pd.DataFrame(columns=['interval','candidate_rank','candidate_l_deg','candidate_b_deg','candidate_z','week','week_start_utc','fava_id','fava_sigma','fava_association','source_name','fava_ra_deg','fava_dec_deg','fava_l_deg','fava_b_deg','separation_deg'])
    return pd.DataFrame(rows).sort_values(["interval","separation_deg","week"])



def _exact_circle_membership(ra_deg, dec_deg, center_ra_deg, center_dec_deg, radius_deg):
    """Boolean membership in an exact spherical circle centered on the supplied ICRS coordinate."""
    ra=np.radians(np.asarray(ra_deg,float)); dec=np.radians(np.asarray(dec_deg,float))
    r0=np.radians(float(center_ra_deg)); d0=np.radians(float(center_dec_deg))
    cossep=np.sin(dec)*np.sin(d0)+np.cos(dec)*np.cos(d0)*np.cos(ra-r0)
    return cossep >= np.cos(np.radians(float(radius_deg)))-1.0e-15


def _exact_target_block_matrix(state, indices, center_ra_deg, center_dec_deg, radius_deg):
    """For one time-reassignment block, tabulate exact-circle membership for every local-direction/time pairing."""
    indices=np.asarray(indices,dtype=np.int64); n=len(indices)
    hour_angle=state.hour_angle_deg[indices][:,None]
    dec=np.broadcast_to(state.declination_mean_deg[indices][:,None],(n,n))
    lst=np.broadcast_to(state.observed_lst_deg[indices][None,:],(n,n))
    angles=[np.broadcast_to(a[indices][None,:],(n,n)) for a in state.precession]
    ra,dc=mean_of_date_to_icrs_with_angles((lst-hour_angle)%360.0,dec,*angles)
    return _exact_circle_membership(ra,dc,center_ra_deg,center_dec_deg,radius_deg)


def _exact_interval_target_statistic(events, state, interval_id, target_interval, ra_deg, dec_deg, config, stream):
    """Exact source-centered statistic for one equal-live interval.

    This reproduces the global randomization convention at an arbitrary sky
    coordinate: time and interval labels are reassigned together within each
    four-hour run block. Only blocks touching the requested interval need be
    materialized, but boundary-crossing blocks retain events from both sides.
    """
    target_interval=int(target_interval)
    relevant=[]
    for inds in state.blocks:
        column_is_target=(state.interval_id[inds]==target_interval)
        if not np.any(column_is_target):
            continue
        M=_exact_target_block_matrix(state,inds,ra_deg,dec_deg,config.aperture_radius_deg)
        relevant.append((inds,M,column_is_target,np.arange(len(inds),dtype=np.int64)))
    observed_interval=np.asarray(interval_id,dtype=np.int16)==target_interval
    N=int(np.sum(_exact_circle_membership(
        events.loc[observed_interval,'ra_deg'].to_numpy(float),
        events.loc[observed_interval,'dec_deg'].to_numpy(float),
        ra_deg,dec_deg,config.aperture_radius_deg)))
    values=np.empty(config.targeted_source_realizations,dtype=np.int32)
    for trial in range(config.targeted_source_realizations):
        rng=realization_rng(config.random_seed,stream,trial); count=0
        for inds,M,column_is_target,row_index in relevant:
            permutation=rng.permutation(len(inds))
            count += int(np.sum(M[row_index,permutation] & column_is_target[permutation]))
        values[trial]=count
    B=float(values.mean()); sB=float(values.std(ddof=1))
    Z=float((N-B)/sB) if sB>0 else np.nan
    pplus=float((1+np.sum(values>=N))/(config.targeted_source_realizations+1))
    return N,B,sB,Z,pplus


def _exact_window_target_statistic(events, config, ra_deg, dec_deg, start, duration_days, stream):
    """Exact source-centered statistic in an externally fixed UTC time window."""
    utc_time=pd.to_datetime(events['utc_time'],utc=True,format='mixed',errors='raise')
    start=pd.Timestamp(start)
    start=start.tz_localize('UTC') if start.tzinfo is None else start.tz_convert('UTC')
    stop=start+pd.Timedelta(days=float(duration_days))
    sub=events.loc[(utc_time>=start)&(utc_time<stop)].copy().reset_index(drop=True)
    gl,gb=equatorial_to_galactic(np.array([float(ra_deg)]),np.array([float(dec_deg)]))
    base={'events':len(sub),'target_ra_deg':float(ra_deg),'target_dec_deg':float(dec_deg),
          'l_deg':float(gl[0]),'b_deg':float(gb[0]),
          'aperture_radius_deg':float(config.aperture_radius_deg),
          'aperture_definition':'exact source-centered spherical circle',
          'trials':int(config.targeted_source_realizations)}
    if sub.empty:
        return {**base,'N':np.nan,'B':np.nan,'sB':np.nan,'Z':np.nan,'one_sided_p':np.nan}
    local_state=randomization_state(sub,config,np.zeros(len(sub),dtype=np.int16))
    matrices=[]
    for inds in local_state.blocks:
        matrices.append((inds,
                         _exact_target_block_matrix(local_state,inds,ra_deg,dec_deg,config.aperture_radius_deg),
                         np.arange(len(inds),dtype=np.int64)))
    N=int(np.sum(_exact_circle_membership(sub['ra_deg'].to_numpy(float),sub['dec_deg'].to_numpy(float),
                                          ra_deg,dec_deg,config.aperture_radius_deg)))
    values=np.empty(config.targeted_source_realizations,dtype=np.int32)
    for trial in range(config.targeted_source_realizations):
        rng=realization_rng(config.random_seed,stream,trial); count=0
        for inds,M,row_index in matrices:
            count += int(M[row_index,rng.permutation(len(inds))].sum())
        values[trial]=count
    B=float(values.mean()); sB=float(values.std(ddof=1))
    Z=float((N-B)/sB) if sB>0 else np.nan
    pplus=float((1+np.sum(values>=N))/(config.targeted_source_realizations+1))
    return {**base,'N':N,'B':B,'sB':sB,'Z':Z,'one_sided_p':pplus}


def curated_source_metrics(top, observed_z, observed_aperture, reference_mean, reference_std,
                           events, state, interval_id, config):
    """Curated exact source-centered interval statistics plus explicitly labeled map-cell context."""
    rows=[]; sources=pd.read_csv(io.StringIO(CURATED_SOURCES_CSV))
    for index,src in sources.iterrows():
        interval_number=int(str(src.period).split('_')[-1]); row_index=interval_number
        target_interval=interval_number-1
        ra,dec=galactic_to_equatorial(np.array([float(src.l_deg)]),np.array([float(src.b_deg)]))
        ra=float(ra[0]); dec=float(dec[0])
        candidates=top[top.period==src.period]
        d=angular_separation_deg(candidates.l_deg.to_numpy(float),candidates.b_deg.to_numpy(float),
                                 float(src.l_deg),float(src.b_deg))
        j=int(np.argmin(d)); c=candidates.iloc[j]
        map_pixel=int(hp.ang2pix(config.nside,np.radians(90-float(src.b_deg)),
                                 np.radians(float(src.l_deg)%360),nest=False))
        print(f"[SOURCE-EXACT] curated {index+1}/{len(sources)}: {src.source}")
        N,B,sB,Z,pplus=_exact_interval_target_statistic(
            events,state,interval_id,target_interval,ra,dec,config,6000+index)
        rows.append({
            'source':src.source,'source_class':src.source_class,'period':src.period,
            'l_deg':float(src.l_deg),'b_deg':float(src.b_deg),'ra_deg':ra,'dec_deg':dec,
            'nearest_l_deg':float(c.l_deg),'nearest_b_deg':float(c.b_deg),
            'nearest_direction_z':float(c.z),'separation_deg':float(d[j]),
            'aperture_radius_deg':float(config.aperture_radius_deg),
            'aperture_definition':'exact source-centered spherical circle',
            'N':N,'B':B,'sB':sB,'Z':Z,'one_sided_p':pplus,
            'trials':int(config.targeted_source_realizations),
            'map_cell_pixel':map_pixel,
            'map_cell_N':int(observed_aperture[row_index,map_pixel]),
            'map_cell_B':float(reference_mean[row_index,map_pixel]),
            'map_cell_sB':float(reference_std[row_index,map_pixel]),
            'map_cell_Z':float(observed_z[row_index,map_pixel])
        })
    return pd.DataFrame(rows)


