def targeted_concordance_summary(targeted):
    if targeted.empty: return pd.DataFrame()
    rows=[]
    work=targeted.dropna(subset=['Z','external_sigma']).copy()
    for name,g in work.groupby('source'):
        if len(g)<2: continue
        tau,pk=kendalltau(g.external_sigma.to_numpy(float),g.Z.to_numpy(float),variant='b')
        rho,ps=spearmanr(g.external_sigma.to_numpy(float),g.Z.to_numpy(float))
        rows.append({'source':name,'weeks':len(g),
                     'kendall_tau_b':float(tau) if np.isfinite(tau) else np.nan,
                     'kendall_p':float(pk) if np.isfinite(pk) else np.nan,
                     'spearman_rho':float(rho) if np.isfinite(rho) else np.nan,
                     'spearman_p':float(ps) if np.isfinite(ps) else np.nan,
                     'max_array_Z':float(g.Z.max()),
                     'max_external_sigma':float(g.external_sigma.max()),
                     'aperture_definition':'exact source-centered spherical circle'})
    return pd.DataFrame(rows).sort_values(['kendall_tau_b','max_array_Z'],ascending=[False,False]) if rows else pd.DataFrame()


def mrk421_temporal_concordance(audit):
    work=audit.dropna(subset=['Z','external_metric']).copy()
    if len(work)<2: return pd.DataFrame()
    tau,pk=kendalltau(work.external_metric.to_numpy(float),work.Z.to_numpy(float),variant='b')
    rho,ps=spearmanr(work.external_metric.to_numpy(float),work.Z.to_numpy(float))
    return pd.DataFrame([{'source':'Mrk 421','days':len(work),
                          'kendall_tau_b':float(tau),'kendall_p':float(pk),
                          'spearman_rho':float(rho),'spearman_p':float(ps),
                          'aperture_definition':'exact source-centered spherical circle'}])


def figure_mrk421_daily(audit,output):
    if audit.empty or audit['Z'].notna().sum()==0: return
    d=audit.copy(); d['date']=pd.to_datetime(d.window_start_utc)
    fig,(a,b)=plt.subplots(2,1,figsize=(9.2,6.8),sharex=True,gridspec_kw={'hspace':.10})
    a.plot(d.date,d.external_metric,'o-',lw=1.8,ms=7); a.set_ylabel('HAWC flux (>1 TeV; Crab Units)',fontsize=14.5); a.grid(alpha=.25)
    b.axhline(0,color='0.35',lw=1.0); b.plot(d.date,d.Z,'o-',lw=1.8,ms=7); b.set_ylabel(r'pentagon-array $Z$',fontsize=14.5); b.set_xlabel('UTC date',fontsize=14.5); b.grid(alpha=.25)
