def fava_concordance_summary(fava_weekly):
    if fava_weekly.empty: return pd.DataFrame()
    rows=[]
    work=fava_weekly.dropna(subset=['Z','external_metric']).copy()
    for name,g in work.groupby('source'):
        if len(g)<2: continue
        tau,pk=kendalltau(g.external_metric.to_numpy(float),g.Z.to_numpy(float),variant='b')
        rho,ps=spearmanr(g.external_metric.to_numpy(float),g.Z.to_numpy(float))
        rows.append({'source':name,'weeks':len(g),
                     'kendall_tau_b':float(tau) if np.isfinite(tau) else np.nan,
                     'kendall_p':float(pk) if np.isfinite(pk) else np.nan,
                     'spearman_rho':float(rho) if np.isfinite(rho) else np.nan,
                     'spearman_p':float(ps) if np.isfinite(ps) else np.nan,
                     'max_array_Z':float(g.Z.max()),
                     'max_external_sigma':float(g.external_metric.max()),
                     'aperture_definition':'exact circle centered on the FAVA flare localization'})
    return pd.DataFrame(rows).sort_values(['kendall_tau_b','max_array_Z'],ascending=[False,False]) if rows else pd.DataFrame()


