def figure_maps(observed_aperture,live_hours,boundaries,primary_l,primary_b,temporal,output):
    rates=observed_aperture[1:]/live_hours[:,None]; positive=rates[rates>0]; vmax=float(np.quantile(positive,.995))
    lon=np.linspace(-180.0,180.0,961); lat=np.linspace(-90.0,90.0,481); L,B=np.meshgrid(lon,lat)
    lr=np.radians(L); br=np.radians(B); samples=np.column_stack([(np.cos(br)*np.cos(lr)).ravel(),(np.cos(br)*np.sin(lr)).ravel(),np.sin(br).ravel()])
    th,ph=hp.pix2ang(16,np.arange(hp.nside2npix(16))); centers=np.column_stack([np.sin(th)*np.cos(ph),np.sin(th)*np.sin(ph),np.cos(th)])
    tree=cKDTree(centers); dist,idx=tree.query(samples,k=4); weights=1/np.maximum(dist,1e-8)**2; weights/=weights.sum(axis=1,keepdims=True); nearest=idx[:,0]
    fig=plt.figure(figsize=(14.8,13.05)); last=None
    for i,rate in enumerate(rates):
        ax=fig.add_subplot(3,2,i+1,projection='mollweide'); field=(rate[idx]*weights).sum(axis=1); field[rate[nearest]==0]=0; field=field.reshape(L.shape)
        last=ax.pcolormesh(np.radians(lon),np.radians(lat),field,cmap=EVENT_CMAP,vmin=0,vmax=vmax,shading='auto',rasterized=True)
        ax.grid(True,color='white',alpha=.32,linewidth=.65); ax.set_xticklabels([]); ax.set_yticklabels([])
        ax.scatter(np.radians((primary_l+180)%360-180),np.radians(primary_b),marker='o',s=118,facecolors='none',edgecolors='#00d7eb',linewidths=2.3,zorder=6)
        r=temporal.iloc[i]; ax.scatter(np.radians((float(r.interval_peak_l_deg)+180)%360-180),np.radians(float(r.interval_peak_b_deg)),marker='*',s=180,c='#ffd238',edgecolors='black',linewidths=.75,zorder=7)
        ax.set_title(f"I{i+1}: {boundaries[i].date()} - {boundaries[i+1].date()}  ({live_hours[i]:.1f} h live)",fontsize=14.2,pad=10)
    fig.subplots_adjust(left=.018,right=.982,top=.888,bottom=.17,wspace=.080,hspace=.255)
    cax=fig.add_axes([.25,.112,.50,.021]); cb=fig.colorbar(last,cax=cax,orientation='horizontal'); cb.set_label(r'observed event rate in an 8$^\circ$ aperture (events h$^{-1}$)',fontsize=15.0); cb.ax.tick_params(labelsize=12.4)
    handles=[Line2D([0],[0],marker='o',linestyle='none',markerfacecolor='none',markeredgecolor='#00d7eb',markeredgewidth=2.0,markersize=10,label='full-archive high-occupancy excess direction'),Line2D([0],[0],marker='*',linestyle='none',markerfacecolor='#ffd238',markeredgecolor='black',markersize=12.5,label='high-occupancy excess direction of that interval')]
    fig.legend(handles=handles,loc='lower center',bbox_to_anchor=(.5,.035),ncol=2,frameon=False,fontsize=12.4); fig.suptitle('Six equal-live-exposure Galactic event-rate maps',fontsize=18.3,y=.982)
    save_figure(fig,output); plt.close(fig)

def figure_evolution(temporal,output):
    start=pd.Timestamp(temporal.iloc[0].start_utc); stops=pd.to_datetime(temporal.stop_utc,utc=True)
    x=(stops-start).dt.total_seconds().to_numpy()/(365.25*86400); full=float(x[-1])
    clive=np.cumsum(temporal.livetime_hours.to_numpy(float)); ct=np.linspace(0,3,450); curve=np.empty_like(ct)
    inside=ct<=full; ilive=np.interp(ct[inside],np.r_[0,x],np.r_[0,clive]); A=float(temporal.iloc[-1].sqrt_exposure_fit)
    curve[inside]=A*np.sqrt(ilive/clive[-1]); curve[~inside]=A*np.sqrt(ct[~inside]/full)
    fig,ax=plt.subplots(figsize=(12.8,7.6))
    ax.plot(ct,curve,'--',color='.2',lw=2.2,label=r'GLS-fitted steady $\sqrt{T}$ scaling')
    ax.scatter(x,temporal.sqrt_exposure_fit,s=70,facecolor='white',edgecolor='.2',label='fitted equal-exposure values')
    ax.scatter(x,temporal.cumulative_z,marker='s',s=75,c='#2454c6',edgecolor='black',label='experimental cumulative significance')
    ax.scatter(x,temporal.fixed_candidate_z,marker='D',s=68,c='#c94b35',edgecolor='black',label='disjoint-interval significance at fixed full-year direction')
    ax.scatter(x,temporal.interval_peak_z,marker='^',s=80,c='#e0a72e',edgecolor='black',label='independently selected interval maximum')
    for level in (3,):
        ax.axhline(level,color='black',lw=1.4,alpha=.8); ax.text(3,level+.06,rf'${level}\sigma$',ha='right')
    ax.axvline(full,color='.45',lw=1.2)
    ax.text(full+.035,.22,'end of measured archive',rotation=90,ha='left',va='bottom',color='.35',fontsize=10.5)
    ax.set_xlim(0,3.05); ax.set_ylim(-0.35,4.55); ax.set_xlabel('elapsed calendar time from the first event (years)',fontsize=15.8)
    ax.set_ylabel(r'local 8$^\circ$ response-scale excess $Z$',fontsize=15.8)
    ax.set_title('Backward investigation and conditional forward extrapolation',fontsize=17.2,pad=18); ax.grid(alpha=.25)
    ax.legend(loc='upper center',bbox_to_anchor=(.5,-.15),ncol=2,fontsize=9.8); fig.subplots_adjust(bottom=.28)
    save_figure(fig,output); plt.close(fig)

