def command_line_config():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--data-dir',type=Path,default=None,
                   help='DAQ folder. If omitted, V12 uses ~/Desktop/Data_Full_5_Center, with the historical Data_Full_5_Cent spelling as a fallback.')
    p.add_argument('--output-dir',type=Path,default=DEFAULT_OUTPUT_DIR)
    p.add_argument('--reference-realizations',type=int,default=100000)
    p.add_argument('--look-elsewhere-realizations',type=int,default=100000)
    p.add_argument('--targeted-source-realizations',type=int,default=10000)
    p.add_argument('--no-figures',action='store_true')
    a=p.parse_args()
    data_dir=resolve_default_data_dir(a.data_dir)
    # Deliberately set both caches to None: the public V12 entry point always
    # reconstructs the complete 44-run archive from the raw DAQ files.
    return Config(data_dir=data_dir,output_dir=a.output_dir,event_cache=None,run_summary_cache=None,
                  reference_realizations=a.reference_realizations,look_elsewhere_realizations=a.look_elsewhere_realizations,
                  targeted_source_realizations=a.targeted_source_realizations,make_figures=not a.no_figures)


def main():
    config=command_line_config()
    Path(config.output_dir).mkdir(parents=True,exist_ok=True)
    log_path=Path(config.output_dir)/'V12_RUN_LOG.txt'
    old_out,old_err=sys.stdout,sys.stderr
    with log_path.open('a',encoding='utf-8',buffering=1) as log:
        sys.stdout=_TeeStream(old_out,log); sys.stderr=_TeeStream(old_err,log)
        try:
            print('\n'+'='*78)
            print(f'[V12-SESSION] {datetime.now().astimezone().isoformat()}')
            run_pipeline(config)
        except BaseException:
            print('[V12-SESSION] Run ended with an exception or interruption; traceback follows.')
            traceback.print_exc()
            raise
        finally:
            sys.stdout=old_out; sys.stderr=old_err

if __name__=='__main__': main()
